const dados = $('Webhook2').item.json.body.data;
const tipo = dados.messageType;

let resultado = {
    messagetype: tipo,
    mensagem: null,
    caption: null,
    mime_type: null,
    midia: null,
    base64: null,
    wa_message_id: dados.key.id,
    stanza_id: dados.contextInfo?.stanzaId || null
};

if (tipo === 'conversation') {
    resultado.mensagem = dados.message.conversation;
} else if (tipo === 'extendedTextMessage') {
    resultado.mensagem = dados.message.extendedTextMessage?.text;
} else if (tipo === 'imageMessage') {
    resultado.mime_type = dados.message.imageMessage.mimetype;
    resultado.caption = dados.message.imageMessage.caption || null;
    resultado.base64 = dados.message.base64;
} else if (tipo === 'audioMessage') {
    resultado.mime_type = dados.message.audioMessage.mimetype;
    resultado.caption = dados.message.audioMessage.caption || null;
    resultado.base64 = dados.message.base64;
} else if (tipo === 'videoMessage') {
    resultado.mime_type = dados.message.videoMessage.mimetype;
    resultado.caption = dados.message.videoMessage.caption || null;
    resultado.base64 = dados.message.base64;
} else if (tipo === 'documentMessage') {
    resultado.mime_type = dados.message.documentMessage.mimetype;
    resultado.caption = dados.message.documentMessage.caption || null;
    resultado.midia = dados.message.documentMessage.fileName || null;
    resultado.base64 = dados.message.base64;
} else if (tipo === 'contactMessage') {
    const nome = dados.message.contactMessage.displayName || 'Contato';
    const vcard = dados.message.contactMessage.vcard || '';
    const telMatch = vcard.match(/TEL[^:]*:(.+)/);
    resultado.mensagem = `👤 ${nome}${telMatch ? '\n' + telMatch[1].trim() : ''}`;
    resultado.caption = vcard || null;
} else if (tipo === 'locationMessage') {
    const lat = dados.message.locationMessage.degreesLatitude;
    const lng = dados.message.locationMessage.degreesLongitude;
    resultado.mensagem = `📍 Localização: https://www.google.com/maps?q=${lat},${lng}`;
} else if (tipo === 'stickerMessage') {
    resultado.mime_type = dados.message.stickerMessage.mimetype;
    resultado.base64 = dados.message.base64;
} else {
    return [];
}

return [{ json: resultado }];

const resposta = $input.item.json;
const registros = resposta.messages && resposta.messages.records ? resposta.messages.records : [];
const msg = registros[0];

if (!msg) {
    return [];
}

let textoNovo = null;
if (msg.message && msg.message.conversation) {
    textoNovo = msg.message.conversation;
} else if (msg.message && msg.message.extendedTextMessage && msg.message.extendedTextMessage.text) {
    textoNovo = msg.message.extendedTextMessage.text;
}

if (!textoNovo) {
    return [];
}

return [{
    json: {
        wa_message_id: msg.key.id,
        mensagem: textoNovo
    }
}];

let base64Data = $('Webhook2').first().json.body?.data?.message?.base64;

if (!base64Data) {
    const response = await this.helpers.httpRequest({
        method: 'POST',
        url: `${$('Webhook2').first().json.body.server_url}/chat/getBase64FromMediaMessage/${$('Webhook2').first().json.body.instance}`,
        headers: {
            'apikey': $('Webhook2').first().json.body.apikey,
            'Content-Type': 'application/json'
        },
        body: {
            message: { key: { id: $('Webhook2').first().json.body.data.key.id } }
        },
        json: true
    });
    base64Data = response.base64;
}

if (!base64Data) {
    throw new Error("O path do Base64 retornou vazio, e o download de fallback também falhou.");
}

const binaryBuffer = Buffer.from(base64Data, 'base64');

return [{
  json: { ...$input.item.json, base64_recuperado: base64Data },
  binary: { audio: await this.helpers.prepareBinaryData(binaryBuffer, 'audio.ogg', 'audio/ogg') }
}];

