const primeira = $('marcar indice da parte').item.json.indice_parte === 0;
const parteTexto = $('marcar indice da parte').item.json.output;
let mensagem, messagetype, mime_type, base64;

if (primeira) {
  mensagem = '📤 Mensagem enviada por ' + $('Webhook2').item.json.body.data.pushName + '\n'
    + ($('verifica messagetype').item.json.messagetype === 'audioMessage'
        ? $('Edit Fields').item.json.mensagem
        : $('verifica messagetype').item.json.mensagem)
    + '\n\n🤖 Resposta do Agente de IA\n' + parteTexto;
  messagetype = $('verifica messagetype').item.json.messagetype === 'audioMessage' ? 'audioMessage' : 'conversation';
  mime_type = $('verifica messagetype').item.json.messagetype === 'audioMessage' ? $('verifica messagetype').item.json.mime_type : null;
  base64 = $('verifica messagetype').item.json.messagetype === 'audioMessage' ? $('b64 para bin').first().json.base64_recuperado : null;
} else {
  mensagem = parteTexto;
  messagetype = 'conversation';
  mime_type = null;
  base64 = null;
}

return [{ json: { ...$('Whats IA').item.json, mensagem, messagetype, mime_type, base64 } }];

const original = $('Webhook2').item.json.body;
const payload = {
  ...original,
  data: {
    ...original.data,
    key: {
      ...original.data.key,
      id: 'REENVIO-' + Date.now()
    },
    message: { conversation: $json.mensagem_combinada },
    messageType: 'conversation',
    messageTimestamp: Math.floor(Date.now() / 1000)
  },
  date_time: new Date().toISOString()
};
return [{ json: { url: $('Webhook2').item.json.webhookUrl, payload } }];

const crypto = require('crypto');

const appId = '2181791';
const key = '8112484fe599e854a7e4';
const secret = '99c9a5f557c1c5b5934f';
const cluster = 'sa1';

const idCliente = $json.id_cliente;
const chatId = $json.chat_id;
const remoteJid = $json.remote_jid;
const messageId = $json.id;

const channel = `private-cliente-${idCliente}`;
const eventName = 'nova-mensagem';
const payload = { chat_id: chatId, remote_jid: remoteJid, message_id: messageId };

const body = JSON.stringify({
    name: eventName,
    channels: [channel],
    data: JSON.stringify(payload)
});

const bodyMd5 = crypto.createHash('md5').update(body).digest('hex');
const timestamp = Math.floor(Date.now() / 1000);

const params = {
    auth_key: key,
    auth_timestamp: timestamp,
    auth_version: '1.0',
    body_md5: bodyMd5
};

const queryString = Object.keys(params).sort().map(k => `${k}=${params[k]}`).join('&');
const stringToSign = `POST\n/apps/${appId}/events\n${queryString}`;
const signature = crypto.createHmac('sha256', secret).update(stringToSign).digest('hex');

const url = `https://api-${cluster}.pusher.com/apps/${appId}/events?${queryString}&auth_signature=${signature}`;

return [{ json: { url, body } }];

